# DK FNB.  Frederiksberg - Nørrebro
#
let fn = path("d3.dk.fnb");

with detail = 4, railway = :first :nopax :removed {
    with link = "line.dk.FNB" {
        track(:station, fn[:fre.yl, :fre.yl + 1seg] << 0.5mo);
        track(fn[:fre.yl + 0.99seg, :nor.yf - 0.99seg] << 0.5mo);
        track(:station, fn[:nor.yf - 1seg, :nor.yf] << 0.5mo);
    }
}

